from typing import List, Set, Any

def common_in_nested_lists(nestedlist: List[List[Any]]) -> Set[Any]:
    assert isinstance(nestedlist, list), "invalid inputs"
    assert all(isinstance(item, list) for item in nestedlist), "invalid inputs"

    if not nestedlist:
        return set()

    common = set(nestedlist[0])
    for sub in nestedlist[1:]:
        common &= set(sub)
        if not common:
            break

    return common
```

